function updateDefectUnitField(){
 const wrap=$('defectUnitWrap');if(!wrap)return;
 const selected=$('relatedTrain')?.value||'';
 const index=selected?state.trains.findIndex((tr,i)=>(tr.id||String(i))===selected):-1;
 const train=index>=0?state.trains[index]:null;
 if(train&&train.unit&&train.unit2){
  wrap.innerHTML=`<label>Unit number<select id="defectUnitNumber" required><option value="">Which unit is affected?</option><option value="${esc(train.unit)}">First unit — ${esc(train.unit)}</option><option value="${esc(train.unit2)}">Second unit — ${esc(train.unit2)}</option></select></label><small class="muted">This train is a double set. Select the affected unit.</small>`;
 }else if(train&&train.unit){
  wrap.innerHTML=`<label>Unit number<input id="defectUnitNumber" value="${esc(train.unit)}" readonly></label><small class="muted">Single set — unit number filled from the train details.</small>`;
 }else{
  wrap.innerHTML=`<label>Unit number (optional)<input id="defectUnitNumber" inputmode="numeric" maxlength="6" placeholder="Enter six-digit unit number"></label>`;
  $('defectUnitNumber')?.addEventListener('input',e=>{e.target.value=e.target.value.replace(/\D/g,'').slice(0,6)});
 }
}
