async function copyEntryToClipboard(entry){const heading=(entry.type==='Incident'&&entry.incidentNumber?`INCIDENT ${entry.incidentNumber}`:String(entry.type||'LOG ENTRY').toUpperCase());const text=`${heading}\n${fmt(entry.timestamp)}\n\n${entryDetails(entry)}`;try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text)}else{const box=document.createElement('textarea');box.value=text;box.setAttribute('readonly','');box.style.position='fixed';box.style.opacity='0';document.body.appendChild(box);box.select();const ok=document.execCommand('copy');box.remove();if(!ok)throw new Error('Clipboard copy was not available')}status('Entry copied to clipboard.')}catch(err){status('Could not copy this entry. Check clipboard permissions.')}}
