function delayMinutesValue(e){if(e?.type!=='Delay')return null;const stored=e.delayMinutes;const match=String(e.text||'').match(/(?:^|\n)\s*Delay:\s*(\d+(?:\.\d+)?)\s*minutes?/i);const value=stored!==undefined&&stored!==null&&stored!==''?Number(stored):(match?Number(match[1]):NaN);return Number.isFinite(value)?value:null}
